-- Autonomous enrichment runner.
--
-- Adds the canonical pepper universe (mirrors src/data/peppers.ts) so the
-- scheduled function can enumerate every pepper needing enrichment server-side,
-- plus autonomous-run state on the settings row.
--
-- NOTE: the pg_cron job that drives the run every 2 minutes is applied
-- operationally (it hard-codes the project URL + anon key), not here, so this
-- migration stays environment-agnostic. See the Autonomous Run notes.

create table if not exists public.pepper_catalog (
  id text primary key,
  name text not null,
  in_stock boolean not null default false
);

insert into public.pepper_catalog (id, name, in_stock)
select e->>0, e->>1, (e->>2)::boolean
from jsonb_array_elements($cat$[["afterglow","Afterglow",true],["aji-amarillo","Aji Amarillo",true],["aji-limon","Aji Limon",true],["ancho","Ancho",true],["calabrian","Calabrian",true],["datil","Datil",true],["de-arbol","De Arbol",true],["devils-breath","Devil's Breath",true],["ghost","Ghost",true],["gochugaru","Gochugaru",true],["hatch-green-chili","Hatch Green Chili",true],["peri-peri","Peri Peri",true],["jalapeno-red","Jalapeño, Red",true],["habanero-red-savina","Habanero, Red Savina",true],["scotch-bonnet","Scotch Bonnet",true],["thai","Thai",true],["trinidad-scorpion","Trinidad Scorpion",true],["wiri-wiri","Wiri Wiri",true],["marash-biber","Marash Biber",true],["bell-pepper","Bell Pepper",false],["poblano","Poblano",false],["jalapeno","Jalapeño",false],["serrano","Serrano",true],["cayenne","Cayenne",true],["hungarian-wax","Hungarian Wax",false],["banana-pepper","Banana Pepper",false],["shishito","Shishito",false],["padron","Padrón",false],["peppadew","Peppadew",true],["espelette","Espelette",false],["aleppo-pepper","Aleppo",true],["urfa-biber","Urfa Biber",true],["kashmiri-chili","Kashmiri Chili",true],["guntur-sannam","Guntur Sannam",false],["byadgi","Byadgi",false],["thai-birds-eye","Thai Bird's Eye",false],["tabasco","Tabasco",true],["habanero","Habanero",true],["carolina-reaper","Carolina Reaper",false],["rocoto","Rocoto",true],["guajillo","Guajillo",true],["pasilla","Pasilla",false],["chipotle","Chipotle (smoked jalapeño)",false],["chipotle-morita","Chipotle Morita",true],["new-mexico-chile","New Mexico Chile",false],["aji-panca","Aji Panca",true],["aji-mirasol","Aji Mirasol",false],["aji-cerezo","Aji Cerezo",false],["aji-dulce","Aji Dulce",false],["charapita","Charapita",true],["biquinho","Biquinho",false],["bahamian-goat","Bahamian Goat",false],["7-pot-douglah","7 Pot, Douglah",false],["7-pot-primo","7 Pot, Primo",false],["manzano","Manzano (Rocoto Manzano)",false],["guindilla","Guindilla",false],["fresno","Fresno",true],["cherry-pepper","Cherry Pepper",false],["cubanelle","Cubanelle",false],["anaheim","Anaheim",false],["cascabel","Cascabel",true],["mulato","Mulato",false],["mirasol","Mirasol (Guajillo fresh type)",false],["tien-tsin","Tien Tsin",true],["er-jing-tiao","Er Jing Tiao",false],["facing-heaven","Facing Heaven",false],["yidu-orange","Yidu - Orange",true],["korean-cheongyang","Korean Cheongyang",false],["siling-labuyo","Siling Labuyo",false],["birds-eye-malaysia","Bird's Eye (Malaysia)",false],["madame-jeanette","Madame Jeanette",false],["adjuma","Adjuma",false],["congo-pepper","Congo Pepper",false],["rocotillo","Rocotillo",false],["aji-colorado","Ají Colorado",false],["aji-verde","Aji Verde",false],["aji-guyana","Aji Guyana",false],["pimento","Pimento (Jamaican Allspice Pepper)",false],["pequin","Pequin",true],["guinea-pepper","Guinea Pepper",false],["sanaam","Sanaam (generic)",false],["chimayo","Chimayo",false],["santa-fe-grande","Santa Fe Grande",false],["aji-pineapple","Aji Pineapple",false],["brazilian-starfish","Brazilian Starfish",false],["bishops-crown","Bishop's Crown",false],["lemon-starrburst","Lemon Starrburst",false],["lemon-habanero","Lemon Habanero",false],["orange-habanero","Orange Habanero",true],["peach-habanero","Peach Habanero",false],["bhutlah-chocolate","Bhutlah, Chocolate",false],["chile-negro","Chile Negro",false],["rocoto-red","Rocoto, Red",false],["rocoto-yellow","Rocoto, Yellow",false],["hinkelhatz","Hinkelhatz",false],["fish-pepper","Fish Pepper",false],["jimmy-nardello","Jimmy Nardello",false],["habanada","Habanada",false],["aji-omnicolor","Aji Omnicolor",false],["aji-mango","Aji Mango",false],["madras-chili","Madras Chili",false],["kambuzi","Kambuzi",false],["chombo","Chombo",false],["trinidad-moruga-scorpion","Trinidad Moruga Scorpion",false],["naga-morich","Naga Morich",false],["dundicut","Dundicut",false],["bird-pepper","Bird Pepper",false],["congo-black","Congo Black",false],["aji-cristal","Aji Cristal",false],["aji-cacho-de-cabra","Aji Cacho de Cabra",false],["merken-pep