,false],["aji-chirel","Aji Chirel",false],["aji-ahuachapan","Aji Ahuachapan",false],["aji-champion","Aji Champion",false],["aji-duke","Aji Duke",false],["aji-cachucha","Aji Cachucha",false],["purple-tiger","Purple Tiger",false],["numex-easter","Numex Easter",false],["black-pearl","Black Pearl",false],["pink-tiger","Pink Tiger",false],["fushimi","Fushimi",false],["tap-de-corti","Tap de Corti",false],["bonda-ma-jacques","Bonda Ma Jacques",false],["aji-largo","Aji Largo",false],["cp115","CP115",false],["jamaican-yellow-mushroom","Jamaican Yellow Mushroom",false],["red-amazon","Red Amazon",false],["jay-peach-ghost-scorpion","Jay Peach Ghost Scorpion",false],["brazilian-ghost","Brazilian Ghost",false],["moruga-blend","Moruga Blend",false],["bhut-jolokia-yellow","Bhut Jolokia, Yellow",false],["habanero-white","Habanero, White",false],["australian-broome","Australian Broome",false],["scarletts-chilli","Scarlett's Chilli",false],["sugar-rush-peach","Sugar Rush Peach",false],["sugar-rush-cream","Sugar Rush Cream",false],["sugar-rush-stripey","Sugar Rush Stripey",false],["naga-smooky-rainbow","Naga Smooky Rainbow",false],["tri-colour-nish","Tri Colour Nish",false],["god-stopper","The God Stopper",false]]$cat$::jsonb) as e
on conflict (id) do update set name = excluded.name, in_stock = excluded.in_stock;

alter table public.enrichment_settings
  add column if not exists autorun_enabled boolean not null default false,
  add column if not exists autorun_status text not null default 'idle',
  add column if not exists autorun_batch_size int not null default 1,
  add column if not exists autorun_locked_at timestamptz,
  add column if not exists autorun_last_tick timestamptz;
